      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Lenvatinib has absolute bioavailability in the order of 85% in humans; the heteroaromatic amide/urea drug supports high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Apatinib shows good oral bioavailability in humans; its amide/pyridine kinase-inhibitor-like structure is relevant to the query and supports high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Venadaparib shows good oral bioavailability in patients; the heteroaromatic amide scaffold supports high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Bromazepam has absolute bioavailability of 86% in humans; its pyridine-containing heteroaromatic structure supports high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Ilomastat did not show good oral bioavailability; this is contradictory, but its peptide-like hydroxamate polarity is not shared by the query, limiting its weight.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C20"],
      "claim": "Aspirin parent has about 17% oral bioavailability in fasting volunteers; this is contradictory, but the low value reflects ester hydrolysis, a mechanism absent in the query's amide/thioether structure.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted high: multiple high-transfer human absolute bioavailability measurements for structurally related amide/heteroaromatic drugs (imidafenacin, tolvaptan, ACT-1004-1239, lenvatinib, apatinib, venadaparib, bromazepam) show F well above 20%, outweighing the weak contradictory ilomastat/aspirin examples and the uncertain physicochemical solubility prior.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query molecule.",
    "Solubility/dissolution and first-pass metabolism of the query are unmeasured.",
    "The low-F mechanisms in ilomastat and aspirin are not mechanistically transferable to the query's amide/thioether structure."
  ],
